          {summary ? formatAmount(summary.outstandingTotal) : ''}
        </dd>

        <dt>Overdue</dt>
        <dd data-testid="dashboard-overdue-count">{summary ? summary.overdueCount : ''}</dd>
      </dl>
    </section>
  );
}

import React, { useEffect, useState } from 'react';

// A client's projects, rendered inside the clients feature when a client is opened. Lists the
// projects done for that client (reusing the project-row-<id>/project-name anchors). Owns its own
// state and data loading (no global store); composed, not branched.
//
// By default it shows only the client's ACTIVE projects — the live work. The finished ones (any
// non-ACTIVE status) and the hidden ones (archived) are kept off the list until the user asks to
// see everything via the show-all toggle; the server returns the full list and this filters it.
type Project = {
  id: number;
  name: string;
  clientId: number;
  clientName: string;
  archived: boolean;
  status: string;
};

export function ClientProjects({ clientId }: { clientId: number }) {
  const [projects, setProjects] = useState<Project[]>([]);
  const [showAll, setShowAll] = useState(false);

  useEffect(() => {
    let active = true;
    async function load() {
      const res = await fetch(`/api/clients/${clientId}/projects`);
      const data = await res.json();
      if (active) {
        setProjects(data);
      }
    }
    void load();
    return () => {
      active = false;
    };
  }, [clientId]);

  const visible = showAll
    ? projects
    : projects.filter((p) => p.status === 'ACTIVE' && !p.archived);

  return (
    <section data-testid="client-detail">
      <h2>Projects</h2>

      <button
        type="button"
        data-testid="client-projects-show-all"
        aria-pressed={showAll}
        onClick={() => setShowAll((s) => !s)}
      >
        {showAll ? 'Show active only' : 'Show finished and hidden'}
      </button>

      {visible.length === 0 ? (
        <p data-testid="client-projects-empty">No projects yet.</p>
      ) : (
        <table data-testid="client-projects-table">
          <thead>
            <tr>
              <th>Name</th>
              <th>Status</th>
            </tr>
          </thead>
          <tbody>
            {visible.map((p) => (
              <tr key={p.id} data-testid={`project-row-${p.id}`}>
                <td data-testid="project-name">{p.name}</td>
                <td data-testid="project-status">{p.status}</td>
              </tr>
            ))}
          </tbody>
        </table>
      )}
    </section>
  );
}

import React, { useEffect, useState } from 'react';

// The invoices feature owns its own state and data loading (no global store). One place that lists
// every invoice across all projects, showing which project each one is for (the project's NAME, a
// cross-entity join surfaced in the UI) and the stage (status) it is at. Served by /api/invoices.
type AllInvoice = {
  id: number;
  projectId: number;
  projectName: string;
  amount: number;
  status: string;
};

function formatAmount(amount: number): string {
  return `$${Number(amount).toLocaleString('en-US', {
    minimumFractionDigits: 2,
    maximumFractionDigits: 2,
  })}`;
}

const PAGE_SIZE = 10;

export function AllInvoicesPage() {
  const [invoices, setInvoices] = useState<AllInvoice[]>([]);
  const [statusFilter, setStatusFilter] = useState('');
  // The full list is large, so it is shown a page at a time with next/previous controls.
  const [page, setPage] = useState(1);

  useEffect(() => {
    async function load() {
      const res = await fetch('/api/invoices');
      setInvoices(await res.json());
    }
    void load();
  }, []);

  // Distinct stages present, so the filter offers exactly the stages the list can show.
  const statuses = Array.from(new Set(invoices.map((inv) => inv.status))).sort();
  const filtered = statusFilter
    ? invoices.filter((inv) => inv.status === statusFilter)
    : invoices;

  // Clamp the page to the available range so changing the filter can't strand us on an empty page.
  const pageCount = Math.max(1, Math.ceil(filtered.length / PAGE_SIZE));
  const currentPage = Math.min(page, pageCount);
  const start = (currentPage - 1) * PAGE_SIZE;
  const visible = filtered.slice(start, start + PAGE_SIZE);

  return (
    <section data-testid="invoices-section">
      <h1>Invoices</h1>

      <label>
        Stage
        <select
          data-testid="invoice-status-filter"
          value={statusFilter}
          onChange={(e) => {
            setStatusFilter(e.target.value);
            setPage(1);
          }}
        >
          <option value="">All</option>
          {statuses.map((status) => (
            <option key={status} value={status}>
              {status}
            </option>
          ))}
        </select>
      </label>

      {filtered.length === 0 ? (
        <p data-testid="all-invoices-empty">No invoices yet.</p>
      ) : (
        <table data-testid="all-invoices-table">
          <thead>
            <tr>
              <th>Project</th>
              <th>Amount</th>
              <th>Stage</th>
            </tr>
          </thead>
          <tbody>
            {visible.map((inv) => (
              <tr key={inv.id} data-testid={`invoice-row-${inv.id}`}>
                <td data-testid="invoice-project">{inv.projectName}</td>
                <td data-testid="invoice-amount">{formatAmount(inv.amount)}</td>
                <td data-testid="invoice-status">{inv.status}</td>
              </tr>
            ))}
          </tbody>
        </table>
      )}

      <nav data-testid="invoice-pagination">
        <button
          type="button"
          data-testid="invoice-page-prev"
          disabled={currentPage <= 1}
          onClick={() => setPage((p) => Math.max(1, p - 1))}
        >
          Previous
        </button>
        <span data-testid="invoice-page-label">{currentPage}</span>
        <button
          type="button"
          data-testid="invoice-page-next"
          disabled={currentPage >= pageCount}
          onClick={() => setPage((p) => Math.min(pageCount, p + 1))}
        >
          Next
        </button>
      </nav>
    </section>
  );
}

import React, { useEffect, useState } from 'react';

// One search box across the whole book: it queries the server's /api/search and shows the matches
// grouped by kind — clients under one heading, projects under another. This feature owns its own
// state and data loading (no global store); it is composed into the shell so it is always on hand.
type Client = { id: number; name: string; email: string };
type Project = { id: number; name: string; clientId: number; clientName: string };
type Results = { clients: Client[]; projects: Project[] };

const EMPTY: Results = { clients: [], projects: [] };

export function GlobalSearch() {
  const [query, setQuery] = useState('');
  const [results, setResults] = useState<Results>(EMPTY);

  useEffect(() => {
    const q = query.trim();
    if (!q) {
      setResults(EMPTY);
      return;
    }
    let live = true;
    void (async () => {
      const res = await fetch(`/api/search?q=${encodeURIComponent(q)}`);
      const data: Results = res.ok ? await res.json() : EMPTY;
      if (live) setResults(data);
    })();
    return () => {
      live = false;
    };
  }, [query]);

  return (
    <section data-testid="global-search-section">
      <input
        data-testid="global-search"
        placeholder="Search clients and projects"
        value={query}
        onChange={(e) => setQuery(e.target.value)}
      />

      <div data-testid="search-clients">
        <h2>Clients</h2>
        {results.clients.map((c) => (
          <div key={c.id} data-testid={`client-row-${c.id}`}>
            <span data-testid="client-name">{c.name}</span>
            <span data-testid="client-email">{c.email}</span>
          </div>
        ))}
      </div>

      <div data-testid="search-projects">
        <h2>Projects</h2>
        {results.projects.map((p) => (
          <div key={p.id} data-testid={`project-row-${p.id}`}>
            <span data-testid="project-name">{p.name}</span>
            <span data-testid="project-client">{p.clientName}</span>
          </div>
        ))}
      </div>
    </section>
  );
}

